// Types dictate template parameters
using InputT = std::string;
using MatchT = std::smatch;

InputT data = "Test 123";
MatchT results;
std::regex pattern("(\\d+)");

// --- Template Instantiation (Compile Time) ---
// Compiler instantiates std::regex_search
// for InputT::iterator and MatchT (basic_match<char>).
bool found = std::regex_search(data, results, pattern);

// --- Matching Execution (Runtime) ---
// The specialized code performs the search algorithm.
if (found) {
    // Access captured groups
    std::string capture = results[1].str();
}
